// Pick first Apify item that has an actual business name
const allItems = $input.all();
let lead = null;
for (const item of allItems) {
  if (item.json && item.json.title && item.json.title.trim() !== '') {
    lead = item.json;
    break;
  }
}
if (!lead) {
  throw new Error('Apify returned no usable business data for this location and industry. Try a different search term or location.');
}

const title = lead.title || 'Unknown Business';
const categoryName = lead.categoryName || (lead.categories && lead.categories[0]) || 'Local Business';
const address = lead.address || lead.street || '';
const city = lead.city || (lead.location && lead.location.city) || '';
const totalScore = lead.totalScore || lead.rating || 0;
const reviewsCount = lead.reviewsCount || 0;
const website = lead.website || '';
const phone = lead.phone || lead.phoneUnformatted || '';

let painPoint;
if (!website) {
  painPoint = title + ' has no website on Google Maps — prospects cannot find them online.';
} else if (reviewsCount < 10) {
  painPoint = title + ' has only ' + reviewsCount + ' reviews — missing the social proof that drives new customers.';
} else if (totalScore < 4.0) {
  painPoint = title + ' sits at ' + totalScore + ' stars — there is clear room to improve their reputation.';
} else if (totalScore >= 4.5 && reviewsCount >= 50) {
  painPoint = title + ' has a strong ' + totalScore + '-star reputation with ' + reviewsCount + ' reviews — primed for growth.';
} else {
  painPoint = title + ' is an established ' + categoryName + ' with room to expand their local reach.';
}

const userPrompt = $('Set Variables').first().json.userPrompt || '';

const systemPrompt = 'You are a direct-response marketing copywriter specializing in cold outreach for local businesses. Your emails convert because they open with a hyper-relevant hook, build desire around a specific outcome, and close with a frictionless CTA. You write like a human, never like a bot. Return ONLY valid raw JSON, no markdown, no code blocks, no explanation.';

const lines = [
  'Write a cold outreach marketing email for this local business.',
  '',
  '=== BUSINESS INTEL ===',
  'Business Name: ' + title,
  'Category: ' + categoryName,
  'Location: ' + address + ', ' + city,
  'Google Rating: ' + totalScore + ' stars (' + reviewsCount + ' reviews)',
  'Website: ' + (website || 'None listed on Google Maps'),
  'Phone: ' + phone,
  '',
  '=== PAIN POINT / HOOK ===',
  painPoint,
  '',
  '=== CORE OFFER (treat this as the value proposition for the email) ===',
  userPrompt,
  '',
  '=== MARKETING BRIEF ===',
  'Apply the AIDA framework (Attention, Interest, Desire, Action):',
  '- ATTENTION: Open with the pain point above — make it feel like research was done on their business.',
  '- INTEREST: Bridge their situation to the offer. What specific outcome does it create for this type of business?',
  '- DESIRE: Add one concrete result or social proof angle that makes the offer feel real and achievable.',
  '- ACTION: End with one low-commitment CTA such as: Got 10 minutes this week? or Want a quick example?',
  '',
  '=== RULES ===',
  '- Subject line: curiosity-driven, mention the business name, under 10 words',
  '- Body: conversational tone, no corporate jargon, no fluff',
  '- Total word count: 80 to 130 words',
  '- Do NOT start with: I hope this finds you well, I wanted to reach out',
  '- Do NOT use bullet points in the body — write in flowing sentences',
  '- End the body with exactly: Reply STOP to opt out.',
  '',
  'Return ONLY this exact JSON with no other text:',
  '{"subject":"...","body":"..."}'
];

const userMessage = lines.join('\n');

const claudePayload = {
  model: 'claude-opus-4-6',
  max_tokens: 1024,
  system: systemPrompt,
  messages: [
    { role: 'user', content: userMessage }
  ]
};

return {
  json: {
    leadName: title,
    category: categoryName,
    address: address,
    city: city,
    rating: totalScore,
    reviews: reviewsCount,
    website: website,
    phone: phone,
    claudePayload: claudePayload
  }
};

const aiResponse = $input.first().json;
const leadData = $('Code — Build AI Prompt').first().json;

let content = '';
if (aiResponse.content && aiResponse.content[0] && aiResponse.content[0].text) {
  content = aiResponse.content[0].text || '';
}

content = content.replace(/```json/gi, '').replace(/```/gi, '').trim();

let emailSubject = 'NearbyNudge Outreach';
let emailBody = '';

try {
  const parsed = JSON.parse(content);
  emailSubject = parsed.subject || emailSubject;
  emailBody = parsed.body || '';
} catch (e) {
  const sm = content.match(/subject[\s\S]{0,10}?([A-Z][^\n"]{5,80})/i);
  const bm = content.match(/body[\s\S]{0,10}?([A-Z][\s\S]{20,})/i);
  if (sm) emailSubject = sm[1].trim().replace(/["']/g, '');
  if (bm) emailBody = bm[1].trim().replace(/["'}]/g, '');
  if (!emailBody) emailBody = content;
}

return {
  json: {
    leadName: leadData.leadName,
    category: leadData.category,
    address: leadData.address,
    city: leadData.city,
    rating: leadData.rating,
    reviews: leadData.reviews,
    website: leadData.website,
    phone: leadData.phone,
    emailSubject: emailSubject,
    emailBody: emailBody
  }
};
